export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function normalize(v){return String(v||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9 ]/g,' ').replace(/\bbones\b/g,'bone').replace(/\bcondyles\b/g,'condyle').replace(/\bvertebrae\b/g,'vertebra').replace(/\s+/g,' ').trim();}
export function levenshtein(a,b){let prev=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){const row=[i];for(let j=1;j<=b.length;j++)row[j]=Math.min(row[j-1]+1,prev[j]+1,prev[j-1]+(a[i-1]!==b[j-1]));prev=row;}return prev[b.length];}
export function acceptedAnswers(s){return [...new Set([s.name,...(s.aliases||[])].map(normalize))];}
export function gradeAnswer(value,target,all){const answer=normalize(value);if(!answer)return false;const valid=acceptedAnswers(target);if(valid.includes(answer))return true;if(all.some(s=>s.id!==target.id&&acceptedAnswers(s).includes(answer)))return false;return valid.some(v=>v.length>=6&&answer.length>=6&&levenshtein(answer,v)<=1);}
export function shuffle(items){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
export function emptyRecord(){return {confidence:'Not studied',attempts:0,correct:0,hinted:0,missed:0,bookmark:false,lastSeen:null};}
export function sanitizeProgress(data,ids){if(!data||data.app!=='biol270-bone-lab'||data.version!==1||!data.records||typeof data.records!=='object')throw new Error('Choose a Bone Lab progress export.');const records={};for(const id of ids){const r=data.records[id];if(!r||typeof r!=='object')continue;const n=emptyRecord();for(const k of ['attempts','correct','hinted','missed'])n[k]=Math.max(0,Math.min(1000000,Number.isFinite(r[k])?Math.floor(r[k]):0));n.correct=Math.min(n.correct,n.attempts);n.hinted=Math.min(n.hinted,n.attempts);n.missed=Math.min(n.missed,n.attempts);n.confidence=['Not studied','Learning','Confident'].includes(r.confidence)?r.confidence:'Not studied';n.bookmark=r.bookmark===true;n.lastSeen=typeof r.lastSeen==='string'&&!Number.isNaN(Date.parse(r.lastSeen))?r.lastSeen:null;records[id]=n;}return records;}
